		openForm: "เ-ะ",
		withFinalForm: "เ-็-",
		example: "เป็น",
	},
	{
		vowel: "แ-ะ",
		openForm: "แ-ะ",
		withFinalForm: "แ-็-",
		example: "แข็ง",
	},
	{
		vowel: "โ-ะ",
		openForm: "โ-ะ",
		withFinalForm: "--",
		example: "กฎ",
	},
	{
		vowel: "เ-าะ",
		openForm: "เ-าะ",
		withFinalForm: "-็อ-",
		example: "น็อต",
	},
	{
		vowel: "เ-อ",
		openForm: "เ-อ",
		withFinalForm: "เ-ิ-",
		example: "เดิน",
		exceptions: [
			{
				finalConsonant: "ย",
				form: "เ-ย",
				example: "เลย",
				note: "before a final ย the อ drops and no สระ อิ is written",
			},
		],
	},
	{
		vowel: "เ-อะ",
		openForm: "เ-อะ",
		withFinalForm: "เ-ิ-",
		// The only entry with no example: common Thai has no closed short
		// เ-อะ syllable to cite, so the with-final form stands on the shipped
		// prose alone (the เ-อะ mnemonic states it; task 3.1 teaches it).
	},
	{
		vowel: "-ัว",
		openForm: "-ัว",
