1	import { ThaiSymbolClass } from "./symbols";
2	
3	// ============================================================================
4	// Sound type — consonant class as a derivable property
5	// ============================================================================
6	// Thai consonant class is a phonetic natural class, not an arbitrary list of
7	// 44 facts:
8	//
9	//   sonorant                 → always low   (derived, no memorisation)
10	//   unaspirated obstruent    → always mid   (derived; this is the whole class)
11	//   aspirate or fricative    → high or low  (only the 11 high ones are learned)
12	//
13	// Everything here reads a consonant's `initialSound` and `isAspirated` and
14	// NOTHING else. In particular the declared class field is never consulted: a
15	// derivation that peeked at it would agree with it by construction and could
16	// never catch the data drifting from the rule the lessons teach.
17	
18	/** The three phonetic buckets every Thai consonant falls into. */
19	export type SoundType =
20		| "sonorant"
21		| "unaspirated-obstruent"
22		| "aspirate-or-fricative";
23	
24	/**
25	 * The one genuine memorisation load in the class system: the 11 high-class
26	 * letters. Every one is an aspirated stop or a fricative — the other two
27	 * buckets never consult this (or any) per-letter table.
28	 */
29	export const HIGH_CLASS_CONSONANTS: readonly string[] = [
30		"ข",
31		"ฃ",
32		"ฉ",
33		"ฐ",
34		"ถ",
35		"ผ",
36		"ฝ",
37		"ศ",
38		"ษ",
39		"ส",
40		"ห",
41	];
42	
43	// Phoneme classes, keyed by the leading token of `initialSound`. These are
44	// definitions of sound types (seven sonorant onsets exist in Thai, and so on),
45	// not per-letter tables: a glyph never appears here, so any consonant — even
46	// one this file has never seen — classifies from its sound alone.
47	const SONORANT_PHONEMES: readonly string[] = [
48		"m",
49		"n",
50		"ng",
51		"y",
52		"r",
53		"l",
54		"w",
55	];
56	const PLAIN_OBSTRUENT_PHONEMES: readonly string[] = [
57		"g",
58		"j",
59		"d",
60		"dt",
61		"b",
62		"bp",
63		// อ, the silent placeholder onset, patterns with the plain stops: it is the
64		// ninth member of the mid class.
65		"silent",
66	];
67	const ASPIRATED_STOP_PHONEMES: readonly string[] = ["kh", "ch", "th", "ph"];
68	const FRICATIVE_PHONEMES: readonly string[] = ["f", "s", "h"];
69	
70	/**
71	 * The leading phoneme token of a stored `initialSound` — the part before the
72	 * first parenthetical gloss, e.g. `"th (same as ฑ and ท)"` → `"th"`.
73	 */
74	function leadingPhoneme(initialSound: string): string | null {
75		const match = initialSound.match(/^([a-z]+)/i);
76		return match ? match[1].toLowerCase() : null;
77	}
78	
79	/**
80	 * Whether a consonant with this `initialSound` must carry `isAspirated: true`
81	 * for the data to be coherent: exactly the aspirated stops kh, ch, th, ph.
82	 * Fricatives (f, s, h) breathe but are not aspirated stops.
83	 */
84	export function expectedAspiration(initialSound: string): boolean {
85		const token = leadingPhoneme(initialSound);
86		return token !== null && ASPIRATED_STOP_PHONEMES.includes(token);
87	}
88	
89	/** The facts classification reads. Deliberately excludes the declared class. */
90	export interface ConsonantSoundFacts {
91		character: string;
92		initialSound: string;
93		isAspirated: boolean;
94	}
95	
96	/**
97	 * The three states a consonant can be in with respect to classification.
98	 * `unclassifiable` always carries its reason, so a letter the rule cannot
99	 * place never reads the same as one nobody has looked at yet.
100	 */
101	export type Classification =
102		| {
103				state: "classified";
104				soundType: SoundType;
105				consonantClass: ThaiSymbolClass;
106		  }
107		| { state: "unclassifiable"; reason: string }
108		| { state: "unclassified" };
109	
110	/** The not-yet-attempted state, for consumers tracking classification lazily. */
111	export const UNCLASSIFIED: Classification = { state: "unclassified" };
112	
113	type PhonemeKind =
114		| "sonorant"
115		| "plain-obstruent"
116		| "aspirated-stop"
117		| "fricative";
118	
119	function phonemeKind(token: string): PhonemeKind | null {
120		if (SONORANT_PHONEMES.includes(token)) return "sonorant";
121		if (PLAIN_OBSTRUENT_PHONEMES.includes(token)) return "plain-obstruent";
122		if (ASPIRATED_STOP_PHONEMES.includes(token)) return "aspirated-stop";
123		if (FRICATIVE_PHONEMES.includes(token)) return "fricative";
124		return null;
125	}
126	
127	/**
128	 * Classify a consonant from its sound facts alone.
129	 *
130	 * Never returns the `unclassified` state — an input the rule cannot place is
131	 * reported as `unclassifiable` with the reason, which the return type
132	 * guarantees.
133	 */
134	export function classifyConsonant(
135		facts: ConsonantSoundFacts,
136	): Exclude<Classification, { state: "unclassified" }> {
137		const token = leadingPhoneme(facts.initialSound);
138		if (token === null) {
139			return {
140				state: "unclassifiable",
141				reason: `initialSound "${facts.initialSound}" has no leading phoneme token`,
142			};
143		}
144	
145		const kind = phonemeKind(token);
146		if (kind === null) {
147			return {
148				state: "unclassifiable",
149				reason: `initialSound token "${token}" is not a recognised Thai onset`,
150			};
151		}
152	
153		// The two fields must agree before either is trusted. This is the check
154		// that caught ฑ and ฒ shipping as unaspirated while their own initialSound
155		// read "th": a derivation that trusted one field silently would have
156		// classed both wrong and let the rule take the blame.
157		if (kind === "aspirated-stop" && !facts.isAspirated) {
158			return {
159				state: "unclassifiable",
160				reason: `initialSound "${facts.initialSound}" names an aspirated stop but isAspirated is false`,
161			};
162		}
163		if (kind !== "aspirated-stop" && facts.isAspirated) {
164			return {
165				state: "unclassifiable",
166				reason: `isAspirated is true but initialSound token "${token}" is not an aspirated stop`,
167			};
168		}
169	
170		if (kind === "sonorant") {
171			return {
172				state: "classified",
173				soundType: "sonorant",
174				consonantClass: ThaiSymbolClass.Low,
175			};
176		}
177		if (kind === "plain-obstruent") {
178			return {
179				state: "classified",
180				soundType: "unaspirated-obstruent",
181				consonantClass: ThaiSymbolClass.Mid,
182			};
183		}
184	
185		// Only the aspirate/fricative bucket consults a per-letter list — the
186		// 11-member residue that genuinely has to be memorised.
187		return {
188			state: "classified",
189			soundType: "aspirate-or-fricative",
190			consonantClass: HIGH_CLASS_CONSONANTS.includes(facts.character)
191				? ThaiSymbolClass.High
192				: ThaiSymbolClass.Low,
193		};
194	}
