75	/** Every `mnemonic:` string literal shipped in `symbols.ts`. */
76	function shippedMnemonics(): string[] {
77		const source = readFileSync(join(DATA_DIR, "symbols.ts"), "utf8");
78		return [...source.matchAll(/mnemonic:\s*("(?:[^"\\]|\\.)*")/g)].map(
79			(match) => JSON.parse(match[1]) as string,
80		);
81	}
82	
83	function loadedCorpus() {
84		if (!isCorpusLoaded(shippedCorpus)) {
85			throw new Error(`corpus did not load: ${shippedCorpus.reason}`);
86		}
87		return shippedCorpus;
88	}
89	
90	/** The shipped artifact with one field overridden, to drive the failure paths. */
91	function corpusWith(overrides: Record<string, unknown>) {
92		return loadOriginalityCorpus({ ...corpusArtifact, ...overrides });
93	}
94	
95	describe("the originality corpus", () => {
96		// AC1 — asserted over the committed artifact rather than the validated
97		// load, so that a corpus built from one set fails *here*, saying which set
98		// is missing, rather than upstream as an opaque "did not load".
99		it("carries n-grams from both licensed PDF sets, tagged by set", () => {
100			const { ngrams, sourceFlags } = corpusArtifact;
101			const tagged = new Set<string>();
102			for (const flags of Object.values(ngrams)) {
103				for (const [name, bit] of Object.entries(sourceFlags)) {
104					if ((flags & bit) !== 0) tagged.add(name);
105				}
106			}
107	
108			expect(tagged).toContain("lesson-notes");
109			expect(tagged).toContain("recording-script");
110		});
111	
112		// AC1 — the tagging is real, not every entry flagged with everything.
113		it("distinguishes the two sets rather than tagging every entry with both", async () => {
114			for (const canary of CANARIES) {
115				const result = await checkOriginality(canary.phrase);
116	
117				expect(result.status).toBe("overlapping");
118				if (result.status !== "overlapping") return;
119				expect(result.overlap.sources).toEqual([canary.source]);
120			}
121		});
122	
123		// AC2
124		it("commits only salted hashes and counts", () => {
125			const corpus = loadedCorpus();
126	
127			for (const [hash, flags] of Object.entries(corpus.ngrams)) {
128				expect(hash).toMatch(/^[0-9a-f]{16}$/);
129				expect(Number.isInteger(flags)).toBe(true);
130				expect(flags).toBeGreaterThan(0);
131				expect(flags).toBeLessThanOrEqual(7);
132			}
133			expect(corpus.salt).toMatch(/^[0-9a-f]+$/);
134		});
135	
136		// AC2
137		it("has no field that reads as a Thai or English phrase", () => {
138			const raw = readFileSync(join(DATA_DIR, "originality-corpus.json"), "utf8");
139	
140			// Matched substrings rather than `expect(raw).not.toMatch(...)`: the
141			// artifact is 600 kB of hex, and asserting on the whole string prints
142			// all of it on failure, burying the one field that actually leaked.
143	
144			// Thai is what the source material is mostly written in; a single Thai
145			// codepoint anywhere in the artifact means text leaked into it.
146			expect(raw.match(/[\u0e00-\u0e7f]+/)?.[0]).toBeUndefined();
147			// Two adjacent words separated by whitespace is the smallest thing that
148			// reads as a phrase. Field names like "sourceFlags" and tags like
149			// "lesson-notes" carry no space and survive this.
150			expect(raw.match(/[A-Za-z]{3,}\s+[A-Za-z]{3,}/)?.[0]).toBeUndefined();
151			// And specifically: the phrases the canary proves ARE in the corpus are
152			// not recoverable from the file that proves it.
153			for (const { phrase } of CANARIES) {
154				expect(raw).not.toContain(phrase);
155				expect(raw).not.toContain(tokenize(phrase).join(" "));
156			}
157		});
158	
159		// AC3
160		it("is queried at n = 5, configured at one site", () => {
161			expect(NGRAM_WIDTH).toBe(5);
162	
163			const module = readFileSync(join(DATA_DIR, "originality.ts"), "utf8");
164			expect(module.match(/NGRAM_WIDTH\s*=/g)).toHaveLength(1);
165	
166			// The Python builder's own default is the same number, and the artifact
167			// records the width it was actually built at.
168			const builder = readFileSync(
169				join(REPO_ROOT, "scripts", "build-originality-corpus.py"),
170				"utf8",
171			);
172			expect(builder).toContain(`DEFAULT_NGRAM_WIDTH = ${NGRAM_WIDTH}`);
173			expect(builder.match(/^DEFAULT_NGRAM_WIDTH = /gm)).toHaveLength(1);
174			expect(loadedCorpus().ngramWidth).toBe(NGRAM_WIDTH);
175		});
176	
177		// AC3 — the constant cannot drift from the data it queries.
178		it("refuses a corpus built at any other width", async () => {
179			const load = corpusWith({ ngramWidth: 8 });
180	
181			expect(isCorpusLoaded(load)).toBe(false);
182			expect(await checkOriginality(ORIGINAL_PROSE, load)).toMatchObject({
183				status: "not-checked",
184			});
185		});
186	});
187	
188	describe("the canary", () => {
189		// AC4
190		it("detects a phrase that is verbatim in each licensed set", async () => {
191			for (const canary of CANARIES) {
192				const result = await checkOriginality(canary.phrase);
193	
194				expect(result.status).toBe("overlapping");
195				if (result.status !== "overlapping") return;
196				expect(result.overlap.ngram).toBe(
197					tokenize(canary.phrase).slice(0, NGRAM_WIDTH).join(" "),
198				);
199			}
200		});
201	
202		// AC4 — the converse, so the canary is not just "everything overlaps".
203		it("clears prose that is not in the source", async () => {
204			await expect(assertOriginal(ORIGINAL_PROSE)).resolves.toBeUndefined();
205		});
206	});
207	
208	describe("the corpus size floor", () => {
209		// AC5
210		it("fails a corpus holding fewer tokens than the floor", async () => {
