			lesson,
		);
	}
}

export class ThaiWord {
	constructor(
		public readonly name: string,
		public readonly romanization: string,
		public readonly meaning: string,
		public readonly tone: ToneValue,
		public readonly toneRule: string,
		public readonly lesson: number,
		public readonly mnemonic?: string,
	) {}
	static fromPlain({
		name,
		romanization,
		meaning,
		tone,
		toneRule,
		lesson,
		mnemonic,
	}: {
		name: string;
		romanization: string;
		meaning: string;
		tone: ToneValue;
		toneRule: string;
		lesson: number;
		mnemonic?: string;
	}): ThaiWord {
		return new ThaiWord(
			name,
			romanization,
			meaning,
			tone,
			toneRule,
			lesson,
			mnemonic,
		);
	}
}

