export enum ThaiSymbolClass {
	High = "high",
	Mid = "mid",
	Low = "low",
}

export type ToneValue = "mid" | "low" | "falling" | "high" | "rising";

// ============================================================================
// Tone Rules
// ============================================================================

export interface ToneRule {
	id: string;
	consonantClass: ThaiSymbolClass;
	syllableType: "live" | "dead-short" | "dead-long";
	resultingTone: ToneValue;
	description: string;
	lesson: number;
}

