		public readonly priority?: number,
		public readonly lesson?: number,
	) {}
}

export class ThaiSymbol extends LearnableItem {
	constructor(
		public readonly character: string,
		public readonly name: string,
		public readonly mnemonic?: string,
		public readonly audioUrl?: string,
		priority?: number,
		lesson?: number,
		public readonly sceneMnemonic?: SceneMnemonic,
	) {
		super(priority, lesson);
	}
	static fromPlain({
		character,
		name,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiSymbol {
		return new ThaiSymbol(
			character,
			name,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
			lesson,
			sceneMnemonic,
		);
	}
}

