		name: string,
		public readonly midClassTone: ToneValue,
		public readonly highClassTone: ToneValue | null,
		public readonly lowClassTone: ToneValue | null,
		mnemonic?: string,
		audioUrl?: string,
		priority?: number,
		lesson?: number,
		sceneMnemonic?: SceneMnemonic,
	) {
		super(character, name, mnemonic, audioUrl, priority, lesson, sceneMnemonic);
	}
	static fromPlain({
		character,
		name,
		midClassTone,
		highClassTone,
		lowClassTone,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		midClassTone: ToneValue;
		highClassTone: ToneValue | null;
		lowClassTone: ToneValue | null;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiToneMark {
		return new ThaiToneMark(
			character,
			name,
			midClassTone,
			highClassTone,
			lowClassTone,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
			lesson,
			sceneMnemonic,
		);
	}
}

export class ThaiWord {
	constructor(
		public readonly name: string,
		public readonly romanization: string,
		public readonly meaning: string,
		public readonly tone: ToneValue,
		public readonly toneRule: string,
		public readonly lesson: number,
		public readonly mnemonic?: string,
		public readonly sceneMnemonic?: SceneMnemonic,
	) {}
	static fromPlain({
		name,
		romanization,
		meaning,
		tone,
		toneRule,
		lesson,
		mnemonic,
		sceneMnemonic,
	}: {
		name: string;
		romanization: string;
		meaning: string;
		tone: ToneValue;
		toneRule: string;
		lesson: number;
		mnemonic?: string;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiWord {
		return new ThaiWord(
			name,
			romanization,
			meaning,
			tone,
			toneRule,
			lesson,
			mnemonic ?? proseFor(sceneMnemonic),
			sceneMnemonic,
		);
	}
}

