		mnemonic,
		sceneMnemonic,
	}: {
		name: string;
		romanization: string;
		meaning: string;
		tone: ToneValue;
		toneRule: string;
		lesson: number;
		mnemonic?: string;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiWord {
		return new ThaiWord(
			name,
			romanization,
			meaning,
			tone,
			toneRule,
			lesson,
			mnemonic ?? proseFor(sceneMnemonic),
			sceneMnemonic,
		);
	}
}

