		tone,
		toneRule,
		lesson,
		mnemonic,
		sceneMnemonic,
	}: {
		name: string;
		romanization: string;
		meaning: string;
		tone: ToneValue;
		toneRule: string;
		lesson: number;
		mnemonic?: string;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiWord {
		return new ThaiWord(
			name,
			romanization,
			meaning,
			tone,
			toneRule,
			lesson,
			mnemonic ?? proseFor(sceneMnemonic),
			sceneMnemonic,
		);
	}
}

export enum ThaiSymbolClass {
	High = "high",
	Mid = "mid",
	Low = "low",
}

export type ToneValue = "mid" | "low" | "falling" | "high" | "rising";

