		audioUrl?: string,
		priority?: number,
		lesson?: number,
		sceneMnemonic?: SceneMnemonic,
	) {
		super(character, name, mnemonic, audioUrl, priority, lesson, sceneMnemonic);
	}
	static fromPlain({
		character,
		name,
		length,
		sound,
		position,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		length: "short" | "long";
		sound: string;
		position: VowelPosition;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiVowel {
		return new ThaiVowel(
			character,
			name,
			length,
			sound,
			position,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
			lesson,
			sceneMnemonic,
		);
	}
}

