		public readonly sceneMnemonic?: SceneMnemonic,
	) {}
	static fromPlain({
		name,
		romanization,
		meaning,
		tone,
		toneRule,
		lesson,
		mnemonic,
		sceneMnemonic,
	}: {
		name: string;
		romanization: string;
		meaning: string;
		tone: ToneValue;
		toneRule: string;
		lesson: number;
