	}
	static fromPlain({
		character,
		name,
		nameRomanized,
		nameMeaning,
		classType,
		hasDeadEnding,
		isAspirated,
		initialSound,
		finalSound,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		nameRomanized: string;
		nameMeaning: string;
		classType: ThaiSymbolClass;
		hasDeadEnding: boolean;
		isAspirated: boolean;
		initialSound: string;
		finalSound: string;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
