	}): ThaiVowel {
		return new ThaiVowel(
			character,
			name,
			length,
			sound,
			position,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
			lesson,
			sceneMnemonic,
		);
	}
}

export class ThaiToneMark extends ThaiSymbol {
	constructor(
		character: string,
		name: string,
