		position: VowelPosition;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiVowel {
		return new ThaiVowel(
			character,
			name,
			length,
			sound,
			position,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
			lesson,
			sceneMnemonic,
		);
	}
}

