	}
	static fromPlain({
		character,
		name,
		midClassTone,
		highClassTone,
		lowClassTone,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		midClassTone: ToneValue;
		highClassTone: ToneValue | null;
