		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiToneMark {
		return new ThaiToneMark(
			character,
			name,
			midClassTone,
			highClassTone,
			lowClassTone,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
