	| "left"
	| "right"
	| "above"
	| "below"
	| "around"
	| "left-above"
	| "left-above-right";

export class ThaiVowel extends ThaiSymbol {
	constructor(
		character: string,
		name: string,
		public readonly length: "short" | "long",
