		public readonly audioUrl?: string,
		priority?: number,
		lesson?: number,
		public readonly sceneMnemonic?: SceneMnemonic,
	) {
		super(priority, lesson);
	}
	static fromPlain({
		character,
		name,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
