		initialSound,
		finalSound,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		nameRomanized: string;
		nameMeaning: string;
		classType: ThaiSymbolClass;
		hasDeadEnding: boolean;
		isAspirated: boolean;
