		mnemonic?: string;
		sceneMnemonic?: SceneMnemonic;
	}): ThaiWord {
		return new ThaiWord(
			name,
			romanization,
			meaning,
			tone,
			toneRule,
			lesson,
			mnemonic ?? proseFor(sceneMnemonic),
			sceneMnemonic,
		);
	}
}

