		key: vowel.character,
		prose: vowel.mnemonic,
		record: vowel.sceneMnemonic,
		carriesTone: false,
	})),
	...toneMarks.map((mark) => ({
		kind: "tone-mark" as const,
		key: mark.character,
		prose: mark.mnemonic,
		record: mark.sceneMnemonic,
		carriesTone: true,
	})),
	...words
		.filter((word) => word.sceneMnemonic !== undefined)
		.map((word) => ({
			kind: "word" as const,
			key: word.name,
			prose: word.mnemonic,
			record: word.sceneMnemonic,
			carriesTone: true,
		})),
